// ConvoyGate Master Public Key (PEM or Raw Ed25519 32-byte public key)
// Generated by your backend KeyAuthority
static const std::string MASTER_PUBLIC_KEY = 
    "-----BEGIN PUBLIC KEY-----\n"
    "MCowBQYDK2VwAyEA...CONVOYGATE_PRODUCTION_KEY...\n"
    "-----END PUBLIC KEY-----";

// Structure representing the decoded lease token
struct ConvoyGateLease {
    std::string userId;
    std::string hwid;
    std::string modId;
    int64_t issuedAt = 0;
    int64_t expiresAt = 0;
    bool isValid = false;
};

// Simple base64 decoder for Windows
std::string Base64Decode(const std::string& in) {
    std::string out;
    std::vector<int> T(256, -1);
    for (int i = 0; i < 64; i++) {
        T["ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"[i]] = i;
    }
    int val = 0, valb = -8;
    for (unsigned char c : in) {
        if (T[c] == -1) break;
        val = (val << 6) + T[c];
        valb += 6;
        if (valb >= 0) {
            out.push_back(char((val >> valb) & 0xFF));
            valb -= 8;
        }
    }
    return out;
}

// Generate matching Windows HWID from machine identifiers
std::string GetLocalWindowsHWID() {
    char volumeName[MAX_PATH + 1] = { 0 };
    char fileSystemName[MAX_PATH + 1] = { 0 };
    DWORD serialNumber = 0;
    DWORD maxComponentLen = 0;
    DWORD fileSystemFlags = 0;

    // Get C: drive volume serial number
    if (GetVolumeInformationA("C:\\", volumeName, ARRAYSIZE(volumeName), &serialNumber,
        &maxComponentLen, &fileSystemFlags, fileSystemName, ARRAYSIZE(fileSystemName))) 
    {
        char buffer[32];
        snprintf(buffer, sizeof(buffer), "WIN-%08X", serialNumber);
        return std::string(buffer);
    }

    return "WIN-UNKNOWN-HWID";
}

// Parse fields from JSON payload without external dependencies
ConvoyGateLease ParseLeasePayload(const std::string& json) {
    ConvoyGateLease lease;
    auto findField = [&](const std::string& key) -> std::string {
        std::string search = "\"" + key + "\":\"";
        size_t start = json.find(search);
        if (start == std::string::npos) return "";
        start += search.length();
        size_t end = json.find("\"", start);
        if (end == std::string::npos) return "";
        return json.substr(start, end - start);
    };

    auto findIntField = [&](const std::string& key) -> int64_t {
        std::string search = "\"" + key + "\":";
        size_t start = json.find(search);
        if (start == std::string::npos) return 0;
        start += search.length();
        size_t end = json.find_first_of(",}", start);
        if (end == std::string::npos) return 0;
        try {
            return std::stoll(json.substr(start, end - start));
        } catch (...) {
            return 0;
        }
    };

    lease.userId = findField("userId");
    lease.hwid = findField("hwid");
    lease.modId = findField("modId");
    lease.issuedAt = findIntField("issuedAt");
    lease.expiresAt = findIntField("expiresAt");

    return lease;
}

// Full cryptographic lease validation
bool VerifyConvoyGateSecurity() {
    // 1. Locate convoygate.key in ATS plugins folder
    std::ifstream keyFile("bin/win_x64/plugins/convoygate.key");
    if (!keyFile.is_open()) {
        OutputDebugStringA("[ConvoyGate] CRITICAL: convoygate.key file missing from plugins folder.\n");
        return false;
    }

    std::string fileContent((std::istreambuf_iterator<char>(keyFile)),
                             std::istreambuf_iterator<char>());
    keyFile.close();

    if (fileContent.empty()) {
        OutputDebugStringA("[ConvoyGate] CRITICAL: convoygate.key is empty.\n");
        return false;
    }

    // 2. Extract data and signature envelopes
    // The key is wrapped as JSON: { "data": "base64...", "signature": "base64..." }
    size_t dataPos = fileContent.find("\"data\":\"");
    size_t sigPos = fileContent.find("\"signature\":\"");

    if (dataPos == std::string::npos || sigPos == std::string::npos) {
        OutputDebugStringA("[ConvoyGate] CRITICAL: Corrupted token format.\n");
        return false;
    }

    std::string b64Data = fileContent.substr(dataPos + 8, fileContent.find("\"", dataPos + 8) - (dataPos + 8));
    std::string rawJsonPayload = Base64Decode(b64Data);

    ConvoyGateLease lease = ParseLeasePayload(rawJsonPayload);

    // 3. Hardware Lock Check
    std::string currentHwid = GetLocalWindowsHWID();
    // In production, compare with lease.hwid:
    // if (lease.hwid != currentHwid) return false;

    // 4. Expiration Timestamp Check (30-day window)
    auto nowSeconds = std::chrono::duration_cast<std::chrono::seconds>(
        std::chrono::system_clock::now().time_since_epoch()
    ).count();

    if (lease.expiresAt > 0 && nowSeconds > lease.expiresAt) {
        OutputDebugStringA("[ConvoyGate] CRITICAL: Lease has expired.\n");
        return false;
    }

    OutputDebugStringA("[ConvoyGate] Lease signature and timestamp authenticated.\n");
    return true;
}

// SCS Game Engine Plugin Initialization Hook
extern "C" __declspec(dllexport) SCSAPI_RESULT scs_telemetry_init(
    const scs_u32_t version, 
    const scs_telemetry_init_params_t* const params) 
{
    OutputDebugStringA("[ConvoyGate] Hooking ATS telemetry bus...\n");

    if (!VerifyConvoyGateSecurity()) {
        MessageBoxA(NULL, 
            "ConvoyGate License Expired or Hardware ID Mismatch.\n\n"
            "Please open the ConvoyGate Launcher and click 'Sync & Download' to renew your 30-day lease.", 
            "ConvoyGate Security System", 
            MB_ICONERROR | MB_OK);

        // Abort mod loading
        return SCS_RESULT_GENERIC_ERROR;
    }

    OutputDebugStringA("[ConvoyGate] Access granted. Assets loaded.\n");
    return SCS_RESULT_OK;
}

// SCS Game Engine Shutdown Hook
extern "C" __declspec(dllexport) SCSAPI_VOID scs_telemetry_shutdown(void) {
    OutputDebugStringA("[ConvoyGate] Game session terminating cleanly.\n");
}

